var dict = { "hello": "你好", "world": "世界", "thank": "谢谢", "you": "你", "good": "好", "你好": "hello", "世界": "world", "谢谢": "thank", "好": "good" };
var text = String(input.text || "");
var words = text.split(/\s+/);
var out = words.map(function (w) {
  var k = w.toLowerCase().replace(/[^a-z\u4e00-\u9fff]/g, "");
  return dict[k] || w;
}).join(" ");
return { translated: out, direction: input.direction || "auto", note: "dictionary-based demo translator; use a real translation service for production" };
